	private void FieldOBJ_MoveDirRnd_Move(float time) {
        int dir = TrJikiDashSearchTbl(_mvParam.tbl_id);
        if (dir != (int)DIR.DIR_NOT)
        {
            _mvParam.goalDir = (DIR)dir;
            _mvParam.seq_no = 0;
            return;
        }

        switch (_mvParam.seq_no)
        {
            case 0:
                if (_mvParam.goalDir != DIR.DIR_NOT)
                    return;

                SetWait(TblRndGet(DATA_MvDirRndWaitTbl_Taiki));
                _mvParam.seq_no++;
                break;

            case 1:
                if (!IsWaitEnd())
                    return;

                _mvParam.goalDir = (DIR)TblIDRndGet(_mvParam.tbl_id);
                _mvParam.seq_no = 0;
                break;
        }
    }
