	private void FieldOBJ_MvRnd_Move(float time) {
        // No default arm: a seq_no outside 0..3 spins here forever (shipped, @01d57b40 `b.hi` to itself).
        while (true)
        {
            switch (_mvParam.seq_no)
            {
                case 0:
                {
                    FieldOBJ_StatusBitOFF_Move();
                    int wait = TblRndGet(DATA_MvDirRndWaitTbl_Move);
                    if (_mvParam.loopcnt > 4 && wait == 0)
                        wait = 32;

                    SetWait(wait);
                    _mvParam.seq_no++;
                    break;
                }

                case 1:
                    if (!IsWaitEnd())
                        return;

                    SetGoalPos((DIR)TblIDRndGet(_mvParam.tbl_id));
                    _mvParam.seq_no++;
                    break;

                case 2:
                    _mv_isMoveStart = true;
                    if ((_mvParam.move_check_type != MV_RND_MOVE_CHECK_RECT || MvRndRectMoveLimitCheck(_mvParam.goalPos)) &&
                        FieldOBJ_GoalPosCheck() == FLDOBJ_MOVE_HIT_BIT_NON)
                    {
                        FieldOBJ_StatusBitON_Move();
                        _mvParam.seq_no++;
                        break;
                    }

                    _mvParam.seq_no = 0;
                    _mvParam.loopcnt++;
                    break;

                case 3:
                    if (!_mvParam.isGoalPos)
                        return;

                    _mvParam.seq_no = 0;
                    _mvParam.loopcnt = 0;
                    FieldOBJ_StatusBitOFF_Move();
                    break;
            }
        }
    }
