	private void CheckSpinDir() {
        int dir = FieldOBJ_DirDispGet();
        for (int i = 0; i < DATA_MvDirKurukuru.Length; i++)
        {
            if (dir == DATA_MvDirKurukuru[i])
            {
                _mvParam.work_id = i;
                break;
            }
        }
    }
	private void FieldOBJ_MoveSpin_Move(float time) {
        // No default arm: a seq_no outside 0..2 spins here forever (shipped, @01d588b8).
        while (true)
        {
            switch (_mvParam.seq_no)
            {
                case 0:
                    SetWait(24);
                    _mvParam.seq_no = 1;
                    break;

                case 1:
                    if (!IsWaitEnd())
                        return;

                    if (_mvParam.spin_dir == (int)DIR.DIR_LEFT)
                        _mvParam.goalDir = (DIR)DATA_MvDirKurukuru[_mvParam.work_id];
                    else if (_mvParam.spin_dir == (int)DIR.DIR_RIGHT)
                        _mvParam.goalDir = (DIR)DATA_MvDirKurukuru[DATA_MvDirKurukuru.Length - 1 - _mvParam.work_id];

                    _mvParam.isGoalPos = false;
                    _mvParam.seq_no++;
                    break;

                case 2:
                    if (!_mvParam.isGoalPos)
                        return;

                    if (_mvParam.goalDir != DIR.DIR_NOT)
                        mv_dir = (int)_mvParam.goalDir;

                    _mvParam.seq_no = 0;
                    _mvParam.work_id = (_mvParam.work_id + 1) % DATA_MvDirKurukuru.Length;
                    break;
            }
        }
    }
	private void FieldOBJ_MoveRewar_Init(float time) {
        MvSpinDirWorkInit((int)DIR.DIR_RIGHT);
    }
	private void FieldOBJ_MoveRewar_Move(float time) {
        int[] dirTblL = new int[] { (int)DIR.DIR_UP, (int)DIR.DIR_LEFT, (int)DIR.DIR_DOWN, (int)DIR.DIR_RIGHT };
        int[] dirTblR = new int[] { (int)DIR.DIR_UP, (int)DIR.DIR_RIGHT, (int)DIR.DIR_DOWN, (int)DIR.DIR_LEFT };

        // No default arm: a seq_no outside 0..2 spins here forever (shipped, @01d58b18).
        while (true)
        {
            switch (_mvParam.seq_no)
            {
                case 0:
                    _mvParam.wait += time;
                    if (!(_mvParam.wait > 0.8f))
                        return;

                    _mvParam.seq_no = 1;
                    _mvParam.wait = 0.0f;
                    break;

                case 1:
                    if (_mvParam.spin_dir == (int)DIR.DIR_RIGHT)
                        FieldOBJ_DirDispCheckSet(dirTblR[_mvParam.work_id]);
                    else if (_mvParam.spin_dir == (int)DIR.DIR_LEFT)
                        FieldOBJ_DirDispCheckSet(dirTblL[_mvParam.work_id]);

                    _mvParam.seq_no++;
                    break;

                case 2:
                    if (!(_mv_YawAngleTime > 1.0f))
                        return;

                    _mvParam.work_id++;
                    if (_mvParam.work_id >= dirTblL.Length)
                    {
                        if (_mvParam.spin_dir == (int)DIR.DIR_LEFT)
                            _mvParam.spin_dir = (int)DIR.DIR_RIGHT;
                        else if (_mvParam.spin_dir == (int)DIR.DIR_RIGHT)
                            _mvParam.spin_dir = (int)DIR.DIR_LEFT;

                        _mvParam.work_id = 0;
                    }

                    _mvParam.seq_no = 0;
                    break;
            }
        }
    }
	private void FieldOBJ_MoveRoute2_Init(float time) {
        _mvParam = new MV_PARAM();

        if (MoveSub_KuruKuruCheck())
            MoveSub_KuruKuruInit();
    }
	private void FieldOBJ_MoveRoute2_Move(float time) {
        int loopCount = 0;

        // No default arm: an unknown seq_no spins here forever (shipped, @01d58dac).
        while (true)
        {
            switch (_mvParam.seq_no)
            {
                case 0:
                {
                    FieldOBJ_StatusBitOFF_Move();
                    int dir = mv_dir;
                    loopCount++;
                    _mv_isMoveStart = false;
                    if (_mvParam.turn_flag)
                    {
                        dir = FieldOBJTool_DirFlip(dir);
                        _mvParam.turn_flag = false;
                    }

                    SetGoalPos((DIR)dir);
                    FieldOBJ_DirMoveSet(dir);
                    _mvParam.seq_no++;

                    if (loopCount > 1000)
                        return;
                    break;
                }

                case 1:
                {
                    int hit = FieldOBJ_GoalPosCheck();
                    if ((hit & FLDOBJ_MOVE_HIT_BIT_LIM) != 0)
                    {
                        _mvParam.turn_flag = true;
                        _mvParam.seq_no = 0;
                        SetGoalPos(DIR.DIR_NOT);
                        break;
                    }

                    if (hit != FLDOBJ_MOVE_HIT_BIT_NON)
                    {
                        _mvParam.object_hit = true;
                        _mvParam.seq_no = 99;
                        _mvParam.object_hit_move_dir = mv_dir;
                        break;
                    }

                    if (MoveSub_KuruKuruCheck())
                        MoveSub_KuruKuruSet();

                    FieldOBJ_StatusBitON_Move();
                    _mvParam.seq_no++;
                    break;
                }

                case 2:
                    if (!_mvParam.isGoalPos)
                        return;

                    if (IsNowDefaultPosXZ())
                        _mvParam.turn_flag = true;

                    if (MoveSub_KuruKuruCheck())
                        MoveSub_KuruKuruEnd();

                    SetGoalPos();
                    _mvParam.seq_no = 0;
                    return;

                case 99:
                {
                    SetGoalPos((DIR)mv_dir);
                    int hit = FieldOBJ_GoalPosCheck();
                    if ((hit & FLDOBJ_MOVE_HIT_BIT_LIM) != 0)
                    {
                        _mvParam.turn_flag = true;
                        _mvParam.seq_no = 0;
                        SetGoalPos(DIR.DIR_NOT);
                        break;
                    }

                    if (hit == FLDOBJ_MOVE_HIT_BIT_NON)
                    {
                        _mvParam.object_hit = false;
                        _mvParam.object_hit_move_dir = (int)DIR.DIR_NOT;
                        _mvParam.seq_no = 1;
                        break;
                    }

                    _mvParam.object_hit = true;
                    _mvParam.seq_no = 99;
                    SetGoalPos(DIR.DIR_NOT);
                    return;
                }
            }
        }
    }
