	private void FieldOBJ_MoveRoute3_Move(float time) {
        int loopCount = 0;

        // No default arm: an unknown seq_no spins here forever (shipped, @01d5ac08).
        while (true)
        {
            switch (_mvParam.seq_no)
            {
                case 0:
                {
                    FieldOBJ_StatusBitOFF_Move();

                    if (_mvParam.turn_no == _mvParam.turn_check_no)
                    {
                        bool isDefault;
                        if (_mvParam.turn_check_type != MV_RT3_CHECK_TYPE_X)
                            isDefault = IsNowDefaultPosZ();
                        else
                            isDefault = IsNowDefaultPosX();

                        if (isDefault)
                            _mvParam.turn_no++;
                    }

                    if (_mvParam.turn_no == MV_RT3_TURN_END_NO && IsNowDefaultPosXZ())
                        _mvParam.turn_no = 0;

                    int dir = DATA_MoveDirTbl((DIRID)_mvParam.tbl_id)[_mvParam.turn_no];
                    _mvParam.dir = dir;
                    FieldOBJ_DirMoveSet(dir);
                    loopCount++;
                    SetGoalPos((DIR)dir);
                    _mvParam.seq_no++;

                    if (loopCount > 1000)
                        return;
                    break;
                }

                case 1:
                {
                    int[] tbl = DATA_MoveDirTbl((DIRID)_mvParam.tbl_id);
                    int hit = FieldOBJ_GoalPosCheck();
                    if ((hit & FLDOBJ_MOVE_HIT_BIT_LIM) != 0)
                    {
#if !SWITCH
                        // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
                        _mvParam.turn_no = global::PcPlatform.PcIntDiv.Rem(_mvParam.turn_no + 1, tbl.Length);
#else
                        _mvParam.turn_no = (_mvParam.turn_no + 1) % tbl.Length;
#endif
                        _mvParam.seq_no = 0;
                        break;
                    }

                    if (hit != FLDOBJ_MOVE_HIT_BIT_NON)
                    {
                        _mvParam.object_hit = true;
                        _mvParam.seq_no = 99;
                        _mvParam.object_hit_move_dir = mv_dir;
                        break;
                    }

                    if (MoveSub_KuruKuruCheck())
                        MoveSub_KuruKuruSet();

                    FieldOBJ_StatusBitON_Move();
                    _mvParam.seq_no++;
                    break;
                }

                case 2:
                    if (!_mvParam.isGoalPos)
                        return;

                    FieldOBJ_StatusBitOFF_Move();
                    if (MoveSub_KuruKuruCheck())
                        MoveSub_KuruKuruEnd();

                    _mvParam.seq_no = 0;
                    SetGoalPos();
                    return;

                case 99:
                {
                    SetGoalPos((DIR)_mvParam.dir);
                    int hit = FieldOBJ_GoalPosCheck();
                    if (hit == FLDOBJ_MOVE_HIT_BIT_NON)
                    {
                        _mvParam.object_hit = false;
                        _mvParam.seq_no = 1;
                        _mvParam.object_hit_move_dir = (int)DIR.DIR_NOT;
                        break;
                    }

                    if ((hit & FLDOBJ_MOVE_HIT_BIT_LIM) == 0)
                    {
                        _mvParam.object_hit = true;
                        _mvParam.seq_no = 99;
                        SetGoalPos(DIR.DIR_NOT);
                        return;
                    }

                    int[] tbl = DATA_MoveDirTbl((DIRID)_mvParam.tbl_id);
#if !SWITCH
                    // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
                    _mvParam.turn_no = global::PcPlatform.PcIntDiv.Rem(_mvParam.turn_no + 1, tbl.Length);
#else
                    _mvParam.turn_no = (_mvParam.turn_no + 1) % tbl.Length;
#endif
                    _mvParam.dir = tbl[_mvParam.turn_no];
                    break;
                }
            }
        }
    }
	private void SetGoalPos() {
        Entity.worldPosition.x = _mvParam.goalPos.x;
        Entity.worldPosition.z = _mvParam.goalPos.z;
        _mvParam._isForceWalkAnime = true;
    }
