	private void FieldOBJ_MovePairTr_Init(float time) {
        _mvParam = new MV_PARAM();
        _mvParam.isZeroFrameAngle = true;

        for (int i = 0; i < GameData.DataManager.TagPlaceData.data.Length; i++)
        {
            if (GameData.DataManager.TagPlaceData.data[i].ID == Entity.name)
                _mvParam.parentname = GameData.DataManager.TagPlaceData.data[i].ParentID;
        }

        for (int i = 0; i < EvDataManager.Instanse.FieldObjectMoveCodes.Count; i++)
        {
            if (EvDataManager.Instanse.FieldObjectMoveCodes[i].Entity.gameObject.name == _mvParam.parentname)
            {
                _mvParam.tbl_no = i;
                _mvParam.seq_no = 1;
            }
        }
    }
	private void FieldOBJ_MovePairTr_Move(float time) {
        _mvParam.isZeroFrameAngle = true;

        switch (_mvParam.seq_no)
        {
            case 0:
                for (int i = 0; i < EvDataManager.Instanse.FieldObjectMoveCodes.Count; i++)
                {
                    if (EvDataManager.Instanse.FieldObjectMoveCodes[i].Entity.gameObject.name == _mvParam.parentname)
                    {
                        _mvParam.tbl_no = i;
                        _mvParam.seq_no = 1;
                    }
                }
                break;

            case 1:
                if (!_mvParam.isGoalPos)
                    return;

                SetGoalPos();

                if (EvDataManager.Instanse.FieldObjectMoveCodes[_mvParam.tbl_no].Entity.logcount < 2)
                    return;

                Vector3 parentPos = EvDataManager.Instanse.FieldObjectMoveCodes[_mvParam.tbl_no].Entity.logPosition[1];
                _mvParam.goalPos.x = parentPos.x;
                _mvParam.goalPos.z = parentPos.z;
                break;
        }
    }
