	private bool MvRndRectMoveLimitCheck(global::UnityEngine.Vector3 pos) {
        Rect rect = new Rect(_mv_defaultPosition.x, _mv_defaultPosition.z, _mv_defaultPosition.x, _mv_defaultPosition.z);

        switch (MoveCode)
        {
            case MV_RND_UL:
                rect.x -= MoveLimitX;
                rect.y -= MoveLimitZ;
                break;

            case MV_RND_UR:
                rect.y -= MoveLimitZ;
                rect.width += MoveLimitX;
                break;

            case MV_RND_DL:
                rect.x -= MoveLimitX;
                rect.height += MoveLimitZ;
                break;

            case MV_RND_DR:
                rect.width += MoveLimitX;
                rect.height += MoveLimitZ;
                break;

            case MV_RND_UDL:
                rect.x -= MoveLimitX;
                rect.y -= MoveLimitZ;
                rect.height += MoveLimitZ;
                break;

            case MV_RND_UDR:
                rect.width += MoveLimitX;
                rect.y -= MoveLimitZ;
                rect.height += MoveLimitZ;
                break;

            case MV_RND_ULR:
                rect.x -= MoveLimitX;
                rect.width += MoveLimitX;
                rect.y -= MoveLimitZ;
                break;

            case MV_RND_DLR:
                rect.x -= MoveLimitX;
                rect.width += MoveLimitX;
                rect.height += MoveLimitZ;
                break;
        }

        return IsInside(pos, rect, Vector3.one);
    }
	private bool IsInside(global::UnityEngine.Vector3 vA, global::UnityEngine.Rect rect, global::UnityEngine.Vector3 size) {
        if (vA.x - size.x * 0.5f <= rect.x && vA.x + size.x * 0.5f >= rect.width)
            return false;

        if (vA.z - size.z * 0.5f <= rect.y && vA.z + size.z * 0.5f >= rect.height)
            return false;

        return true;
    }
