	private int FieldOBJ_GoalPosCheck() {
        int ret = FLDOBJ_MOVE_HIT_BIT_NON;

        if (FieldOBJ_MoveHitCheckLimit(_mvParam.goalPos.x, _mvParam.goalPos.z))
            ret |= FLDOBJ_MOVE_HIT_BIT_LIM;

        // dir is never read by the callee (w1 is not set @01d58408); the move direction is the natural argument.
        if (FieldOBJ_MoveHitCheckAttr(_mvParam.goalPos.x, _mvParam.goalPos.z, _mvParam.dir))
            ret |= FLDOBJ_MOVE_HIT_BIT_ATTR;

        if (FieldOBJ_GoalPosHitCheckFellow())
            ret |= FLDOBJ_MOVE_HIT_BIT_OBJ;

        return ret;
    }
	private bool FieldOBJ_MoveHitCheckLimit(float x, float z) {
        float absX = Math.Abs(x);
        if (absX < _movelimit_Min.x || _movelimit_Max.x < absX)
            return true;

        float absZ = Math.Abs(z);
        if (absZ < _movelimit_Min.y || _movelimit_Max.y < absZ)
            return true;

        return false;
    }
	private bool FieldOBJ_GoalPosHitCheckFellow() {
        if (EvDataManager.Instanse == null)
            return false;

        for (int i = 0; i < Entity.EventParams.NearObject.Length; i++)
        {
            int index = Entity.EventParams.NearObject[i];
            if (index < 0)
                continue;

            FieldObjectEntity entity = EvDataManager.Instanse._fieldObjectEntity[index];
            if (entity == null)
                continue;

            float dx = _mvParam.goalPos.x - entity.worldPosition.x;
            float dz = _mvParam.goalPos.z - entity.worldPosition.z;
            if (dx * dx + dz * dz < 1.0f)
                return true;

            if (entity.EventParams.MoveCodeIndex == -1)
                continue;

            FieldObjectMoveCode moveCode = EvDataManager.Instanse.FieldObjectMoveCodes[entity.EventParams.MoveCodeIndex];
            dx = _mvParam.goalPos.x - moveCode.MvParamGoalPos.x;
            dz = _mvParam.goalPos.z - moveCode.MvParamGoalPos.z;
            if (dx * dx + dz * dz < 1.0f)
                return true;
        }

        if (IsPlayerHeight && PlayerGridDistance <= 1)
        {
            float dx = _mvParam.goalPos.x - playerPosition.x;
            float dz = _mvParam.goalPos.z - playerPosition.z;
            if (dx * dx + dz * dz < 1.0f)
                return true;
        }

        return false;
    }
	private bool FieldOBJ_MoveHitCheckAttr(float x, float z, int dir) {
        Vector2Int grid = FieldObjectEntity.PositionToGrid(new Vector3(x, 0.0f, z));
        GameManager.GetAttribute(grid, out int code, out int stop, false);

        var attribute = GameManager.GetAttributeTable(code);
        if (attribute == null || !attribute.Entry)
            return true;

        return stop == 128;
    }
