	private int TrJikiDashSearch() {
        if (Ev_Type != EV_TYPE_TRAINER && Ev_Type != EV_TYPE_TRAINER_EYEALL)
            return (int)DIR.DIR_NOT;

        int i = 0;
        int code;
        do
        {
            code = enable_code[i];
            if (code == MoveCode)
            {
                if (!isPlayerRun)
                    return (int)DIR.DIR_NOT;

                if (!Mathf.Approximately(playerPosition.y, Entity.worldPosition.y))
                    return (int)DIR.DIR_NOT;

                int px = playerGridPosition.x;
                int pz = playerGridPosition.y;
                int range = MoveParam0;
                int gx = Entity.gridPosition.x;
                int gz = Entity.gridPosition.y;

                if (gx + range < px)
                    return (int)DIR.DIR_NOT;
                if (gx - range > px)
                    return (int)DIR.DIR_NOT;
                if (gz - range > pz)
                    return (int)DIR.DIR_NOT;
                if (gz + range < pz)
                    return (int)DIR.DIR_NOT;

                return FieldOBJTool_DirRange(gx, gz, px, pz);
            }

            i++;
        }
        while (code != MV_CODE_NOT);

        return (int)DIR.DIR_NOT;
    }
	private int TrJikiDashSearchTbl(int id) {
        int[] tbl = DATA_MoveDirTbl((DIRID)id);
        if (tbl == null || tbl.Length < 2)
            return (int)DIR.DIR_NOT;

        int dir = TrJikiDashSearch();
        if (dir == (int)DIR.DIR_NOT)
            return (int)DIR.DIR_NOT;

        for (int i = 0; i < tbl.Length; i++)
        {
            if (tbl[i] == dir)
                return dir;
        }

        int gx = Entity.gridPosition.x;
        int gz = Entity.gridPosition.y;
        int px = playerGridPosition.x;
        int pz = playerGridPosition.y;

        int dirX = (int)DIR.DIR_NOT;
        if (gx > px)
            dirX = (int)DIR.DIR_LEFT;
        else if (gx < px)
            dirX = (int)DIR.DIR_RIGHT;

        int dirZ = (int)DIR.DIR_NOT;
        if (gz > pz)
            dirZ = (int)DIR.DIR_UP;
        else if (gz < pz)
            dirZ = (int)DIR.DIR_DOWN;

        if (dirX == (int)DIR.DIR_NOT)
        {
            for (int i = 0; i < tbl.Length; i++)
            {
                if (tbl[i] == dirZ)
                    return dirZ;
            }
        }
        else if (dirZ == (int)DIR.DIR_NOT)
        {
            for (int i = 0; i < tbl.Length; i++)
            {
                if (tbl[i] == dirX)
                    return dirX;
            }
        }
        else
        {
            for (int i = 0; i < tbl.Length; i++)
            {
                if (tbl[i] == dirX)
                    return dirX;
                if (tbl[i] == dirZ)
                    return dirZ;
            }
        }

        return (int)DIR.DIR_NOT;
    }
	private int FieldOBJTool_DirRange(int ax, int az, int bx, int bz) {
        if (ax > bx)
            return (int)DIR.DIR_LEFT;
        if (ax < bx)
            return (int)DIR.DIR_RIGHT;
        if (az > bz)
            return (int)DIR.DIR_UP;

        return (int)DIR.DIR_DOWN;
    }
