	private void SubMoveKyoro_Init() {
        _subWork = new SUBWORK();
        _subWork.max_count = MoveParam1;
    }
	private bool SubMoveKyoro_StartCheck() {
        switch (_subWork.check_seq_no)
        {
            case 0:
                if (_subWork.walk_count >= _subWork.max_count)
                {
                    _subWork.check_seq_no = 2;
                    _subWork.move_seq_no = 0;
                    _subWork.walk_count = 0;
                    return true;
                }
                break;
            case 2:
                return true;
        }
        return false;
    }
	private bool SubMoveKyoro_Move() {
        while (true)
        {
            switch (_subWork.move_seq_no)
            {
                case 0:
                {
                    int[] dirTypeTbl = new int[] { DIR_H_TYPE, DIR_H_TYPE, DIR_V_TYPE, DIR_V_TYPE };
                    _subWork.origin_dir = FieldOBJ_DirDispGet();
                    _subWork.dir_type = dirTypeTbl[_subWork.origin_dir];
                    _subWork.move_seq_no++;
                    break;
                }

                case 1:
                {
                    DIR[][] dirTbl = new DIR[][]
                    {
                        new DIR[] { DIR.DIR_LEFT, DIR.DIR_RIGHT },
                        new DIR[] { DIR.DIR_UP, DIR.DIR_DOWN },
                    };
                    _mvParam.goalDir = dirTbl[_subWork.dir_type][_subWork.dir_no];
                    _subWork.move_seq_no++;
                    break;
                }

                case 2:
                    if (_mvParam.goalDir != DIR.DIR_NOT)
                        return true;

                    _subWork.move_seq_no = 3;
                    SetWait(KYORO_WAIT_FRAME);
                    break;

                case 3:
                    if (!IsWaitEnd())
                        return true;

                    _subWork.wait = 0;
                    _subWork.dir_count++;
                    if (_subWork.dir_count >= KYORO_COUNT_MAX)
                    {
                        _subWork.dir_count = 0;
                        _subWork.check_seq_no = 0;
                        _subWork.move_seq_no = 4;
                        break;
                    }

                    _subWork.move_seq_no = 1;
                    _subWork.dir_no = (_subWork.dir_no + 1) & 1;
                    return true;

                default:
                    return false;
            }
        }
    }
	private void SubMoveSpinStop_Init() {
        _subWork.max_count = MoveParam1;
        _subWork.dir_type = Ev_Type == EV_TYPE_TRAINER_SPIN_STOP_L ? SPIN_STOP_L_TYPE : SPIN_STOP_R_TYPE;
    }
	private bool SubMoveSpinStop_StartCheck() {
        if (_subWork.check_seq_no != 0)
            return true;

        if (_subWork.walk_count < _subWork.max_count)
        {
            _subWork.check_seq_no = 0;
            return false;
        }

        _subWork.check_seq_no = 1;
        _subWork.move_seq_no = 0;
        _subWork.walk_count = 0;
        return true;
    }
	private bool SubMoveSpinStop_Move() {
        while (true)
        {
            switch (_subWork.move_seq_no)
            {
                case 0:
                    _subWork.origin_dir = FieldOBJ_DirDispGet();
                    _subWork.dir_no = 0;
                    _subWork.move_seq_no++;
                    break;

                case 1:
                    if (_subWork.dir_type == SPIN_STOP_L_TYPE)
                        _mvParam.goalDir = (DIR)DATA_MvDirKurukuru[_subWork.dir_no];
                    else
                        _mvParam.goalDir = (DIR)DATA_MvDirKurukuru[DATA_MvDirKurukuru.Length - 1 - _subWork.dir_no];

                    _subWork.move_seq_no++;
                    break;

                case 2:
                    if (_mvParam.goalDir != DIR.DIR_NOT)
                        return true;

                    _subWork.move_seq_no = 3;
                    SetWait(SPIN_STOP_WAIT_FRAME);
                    break;

                case 3:
                    if (!IsWaitEnd())
                        return true;

                    _subWork.wait = 0;
                    _subWork.dir_count++;
                    if (_subWork.dir_count >= SPIN_STOP_COUNT_MAX)
                    {
                        _subWork.dir_count = 0;
                        _subWork.check_seq_no = 0;
                        _subWork.move_seq_no = 4;
                        break;
                    }

                    _subWork.move_seq_no = 1;
                    _subWork.dir_no = (_subWork.dir_no + 1) % DATA_MvDirKurukuru.Length;
                    return true;

                default:
                    return false;
            }
        }
    }
	private int FieldOBJ_DirDispGet() {
        float angle = (Entity.yawAngle + 360.0f) % 360.0f;

        if (angle < 45.0f)
            return (int)DIR.DIR_DOWN;
        else if (angle < 135.0f)
            return (int)DIR.DIR_LEFT;
        else if (angle < 225.0f)
            return (int)DIR.DIR_UP;
        else if (angle < 315.0f)
            return (int)DIR.DIR_RIGHT;
        else
            return (int)DIR.DIR_DOWN;
    }
