	public void MoveCodeUpdate(float time, ref global::UnityEngine.Vector3 pWorld, ref global::UnityEngine.Vector2Int pGrid, bool isrun) {
        if (!Entity.gameObject.activeInHierarchy)
            return;

        if (MoveCode == MV_DMY)
            return;

        if (_moveProc == null)
            return;

        if (SmartPoint.Components.Fader.isBusy)
            return;

        playerPosition = pWorld;
        playerGridPosition = pGrid;
        isPlayerRun = isrun;

        if (FieldConnector.IsSetupOperationRunning)
            return;

        if (Entity.IsBusyRouteMove)
            return;

        if (MvState == MV_STATE.Encount || MvState == MV_STATE.Stop || MvState == MV_STATE.TrainerStop)
        {
            Entity.moveVector = Vector3.zero;
            return;
        }

        _mvParam.isGoalPos = false;

        Vector3 nowPos = Entity.worldPosition;
        Vector3 goalPos = _mvParam.goalPos;
        float distZ = Mathf.Abs(Mathf.Floor((goalPos.z - nowPos.z) * 100.0f) * 0.01f);
        float distX = Mathf.Abs(Mathf.Floor((goalPos.x - nowPos.x) * 100.0f) * 0.01f);
#if PC_UNLOCKED_FPS
        if (_mvParam.goalDir == DIR.DIR_NOT && distZ < 0.13333334f * PcPlatform.PcFrameClock.Frames && distX < 0.13333334f * PcPlatform.PcFrameClock.Frames && IsWaitEnd())
#else
        if (_mvParam.goalDir == DIR.DIR_NOT && distZ < 0.13333334f && distX < 0.13333334f && IsWaitEnd())
#endif
        {
            _mvParam.isGoalPos = true;

            if (_mvParam.walkCountStart)
            {
                _subWork.walk_count++;
                _mvParam.walkCountStart = false;
            }

            if (IsSubProcActive() && SubStart())
                _isSubProc = true;
        }

        if (!_isSubProc)
            _moveProc.UpdateProc(time);
        else if (!SubUpdate())
            _isSubProc = false;

        bool move;
        if (_mvParam.waitTime <= _mvParam.endWait)
        {
            _mvParam.waitTime += time;
            move = false;
        }
        else if (_mvParam.goalDir != DIR.DIR_NOT)
        {
            _isEyeHitStop = true;
            if (UpdateAngle(GetDirAngle(_mvParam.goalDir), 30.0f, _mvParam.isZeroFrameAngle))
            {
                move = true;
            }
            else
            {
                move = false;
                _isEyeHitStop = false;
                _mvParam.goalDir = DIR.DIR_NOT;
            }
        }
        else
        {
            nowPos = Entity.worldPosition;
            goalPos = _mvParam.goalPos;
            Entity.moveVector = Vector3.zero;

            float moveX = Mathf.Floor((goalPos.x - nowPos.x) * 100.0f) * 0.01f;
            float moveZ = Mathf.Floor((goalPos.z - nowPos.z) * 100.0f) * 0.01f;
#if PC_UNLOCKED_FPS
            if (moveX < 0.13333334f * PcPlatform.PcFrameClock.Frames && moveX > -0.13333334f * PcPlatform.PcFrameClock.Frames)
#else
            if (moveX < 0.13333334f && moveX > -0.13333334f)
#endif
                moveX = 0.0f;
#if PC_UNLOCKED_FPS
            if (moveZ < 0.13333334f * PcPlatform.PcFrameClock.Frames && moveZ > -0.13333334f * PcPlatform.PcFrameClock.Frames)
#else
            if (moveZ < 0.13333334f && moveZ > -0.13333334f)
#endif
                moveZ = 0.0f;

            int dir = (int)DIR.DIR_NOT;
            if (_mvParam.object_hit)
                dir = _mvParam.object_hit_move_dir;

            if (dir == (int)DIR.DIR_NOT)
            {
                if (moveX < 0.0f)
                    dir = (int)DIR.DIR_RIGHT;
                else if (moveX > 0.0f)
                    dir = (int)DIR.DIR_LEFT;
                else if (moveZ < 0.0f)
                    dir = (int)DIR.DIR_UP;
                else if (moveZ > 0.0f)
                    dir = (int)DIR.DIR_DOWN;
            }

            float angle = GetDirAngle((DIR)dir);

            if (_mvParam.krkr_start)
            {
#if PC_UNLOCKED_FPS
                Entity.yawAngle += 22.5f * PcPlatform.PcFrameClock.Frames;
#else
                Entity.yawAngle += 22.5f;
#endif
                if (Entity.yawAngle > 360.0f)
                    Entity.yawAngle -= 360.0f;
            }

            move = false;
            if (dir == (int)DIR.DIR_NOT || Entity.yawAngle == angle || _mvParam.krkr_start)
            {
                _isEyeHitStop = false;
            }
            else
            {
                move = UpdateAngle(angle, 30.0f, _mvParam.isZeroFrameAngle);
                _isEyeHitStop = true;
            }

            if (moveX != 0.0f)
            {
#if PC_UNLOCKED_FPS
                if (moveX < -0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.x = -0.13333334f * PcPlatform.PcFrameClock.Frames;
                else if (moveX > 0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.x = 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                if (moveX < -0.13333334f)
                    Entity.moveVector.x = -0.13333334f;
                else if (moveX > 0.13333334f)
                    Entity.moveVector.x = 0.13333334f;
#endif
                else
                    Entity.moveVector.x = moveX;

                move = true;
            }
            else if (moveZ != 0.0f)
            {
#if PC_UNLOCKED_FPS
                if (moveZ < -0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.z = -0.13333334f * PcPlatform.PcFrameClock.Frames;
                else if (moveZ > 0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.z = 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                if (moveZ < -0.13333334f)
                    Entity.moveVector.z = -0.13333334f;
                else if (moveZ > 0.13333334f)
                    Entity.moveVector.z = 0.13333334f;
#endif
                else
                    Entity.moveVector.z = moveZ;

                move = true;
            }

            bool forceWalk = _mvParam._isForceWalkAnime;
            _mvParam._isForceWalkAnime = false;
            move |= forceWalk;
        }

        if (PlayerGridDistance < 300)
            MoveCodeUpdateAfter(move, time);
    }
	private bool UpdateAngle(float dir, float anglespd, bool zeroframe = false) {
        if (!zeroframe)
        {
            float diff = dir - Entity.yawAngle;
            diff = (diff < 0.0f ? diff + 360.0f : diff) % 360.0f;
            if (diff > 180.0f)
                diff -= 360.0f;

#if PC_UNLOCKED_FPS
            // PC (s37): anglespd is degrees per shipped 30 Hz frame (callers: 30 / 30 / 22.5, all per Update)
            anglespd *= PcPlatform.PcFrameClock.Frames;
            float add = diff;
#else
            float add = diff;
#endif
            if (diff < -anglespd)
                add = -anglespd;
            else if (diff > anglespd)
                add = anglespd;

            Entity.yawAngle += add;
            if (!Mathf.Approximately(Mathf.Floor(Entity.yawAngle * 100.0f) * 0.01f, dir))
                return true;
        }

        Entity.yawAngle = dir;
        return false;
    }
	private void SetWait(int frame) {
        if (frame > 0)
            _mvParam.endWait = frame / 30.0f;
        else
            _mvParam.endWait = 0.0f;
        _mvParam.waitTime = 0.0f;
    }
	private bool IsWaitEnd() {
        return _mvParam.endWait <= _mvParam.waitTime;
    }
	private int GetDirAngle(global::DIR dir) {
        switch (dir)
        {
            case DIR.DIR_UP:
                return 180;
            case DIR.DIR_DOWN:
                return 0;
            case DIR.DIR_LEFT:
                return 90;
            case DIR.DIR_RIGHT:
                return 270;
            case DIR.DIR_LEFTUP:
                return 125;
            case DIR.DIR_RIGHTUP:
                return 315;
            case DIR.DIR_LEFTDOWN:
                return 45;
            case DIR.DIR_RIGHTDOWN:
                return 315;
            default:
                return -1;
        }
    }
	private void SetGoalPos(global::DIR dir) {
        _mvParam.isGoalPos = false;
        _mvParam.goalPos.x = -Entity.gridPosition.x;
        _mvParam.goalPos.y = Entity.transform.position.y;
        _mvParam.goalPos.z = Entity.gridPosition.y;
        _mvParam.walkCountStart = true;

        switch (dir)
        {
            case DIR.DIR_NOT:
                _mvParam.isGoalPos = true;
                _mvParam.walkCountStart = false;
                break;

            case DIR.DIR_UP:
                _mvParam.goalPos.z += -1.0f;
                break;

            case DIR.DIR_DOWN:
                _mvParam.goalPos.z += 1.0f;
                break;

            case DIR.DIR_LEFT:
                _mvParam.goalPos.x += 1.0f;
                break;

            case DIR.DIR_RIGHT:
                _mvParam.goalPos.x += -1.0f;
                break;

            case DIR.DIR_LEFTUP:
                _mvParam.goalPos += new Vector3(1.0f, 0.0f, -1.0f);
                break;

            case DIR.DIR_RIGHTUP:
                _mvParam.goalPos += new Vector3(-1.0f, 0.0f, -1.0f);
                break;

            case DIR.DIR_LEFTDOWN:
                _mvParam.goalPos += new Vector3(1.0f, 0.0f, 1.0f);
                break;

            case DIR.DIR_RIGHTDOWN:
                _mvParam.goalPos += new Vector3(-1.0f, 0.0f, 1.0f);
                break;
        }
    }
	private bool IsNowDefaultPosX() {
        return Mathf.Floor((_mv_defaultPosition.x - Entity.worldPosition.x) * 100.0f) * 0.01f == 0.0f;
    }
	private bool IsNowDefaultPosZ() {
        return Mathf.Floor((_mv_defaultPosition.z - Entity.worldPosition.z) * 100.0f) * 0.01f == 0.0f;
    }
	private bool IsNowDefaultPosXZ() {
        return IsNowDefaultPosX() && IsNowDefaultPosZ();
    }
	private void MoveCodeUpdateAfter(bool move, float time) {
        switch (EntityType)
        {
            case 2:
                if (move)
                {
                    charaEntity.GetAnimationPlayer().Play(charaEntity.GetWalkAnimationIndex(), 0.2f, 0.0f);
                }
                else
                {
                    charaEntity.GetIdleAnimationIndex(out int index, out float duration);
                    charaEntity.GetAnimationPlayer().Play(index, duration, 0.0f);
                }
                break;

            case 1:
                pokeEntity.GetAnimationPlayer().Play(move ? 1 : pokeEntity.GetIdleAnimationIndex(), 0.2f, 0.0f);
                break;
        }
    }
	private void AnimeStop() {
        switch (EntityType)
        {
            case 2:
                charaEntity.GetIdleAnimationIndex(out int index, out float duration);
                charaEntity.GetAnimationPlayer().Play(index, duration, 0.0f);
                break;

            case 1:
                pokeEntity.GetAnimationPlayer().Play(pokeEntity.GetIdleAnimationIndex(), 0.2f, 0.0f);
                break;
        }
    }
	public void MoveCodeLateUpdate(float deltatime) {
        // Empty
    }
	public bool TrainerEyeUpdate(ref global::UnityEngine.Vector3 moveVector, ref global::UnityEngine.Vector2 hitpos) {
        if (MvState == MV_STATE.Encount || MvState == MV_STATE.Stop || MvState == MV_STATE.TrainerStop)
            return false;

        if (Entity == null)
            return false;

        if (!Entity.gameObject.activeInHierarchy)
            return false;

        switch (Ev_Type)
        {
            case EV_TYPE_NORMAL:
            case EV_TYPE_ITEM:
            case EV_TYPE_MSG:
                return false;
        }

        if (TrainerID == TrainerID.NONE)
            return false;

        if (TrainerWork.GetWinFlag(TrainerID))
            return false;

        if (TrainerWork.IsTagTranier(TrainerID, out TrainerID tagTrainer) &&
            !FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_PAIR) &&
            PlayerWork.playerParty.GetMemberCountEx(Pml.PokeParty.CountType.BATTLE_ENABLE) < 2)
            return false;

        if (MoveParam0 < 1)
            return false;

        if (_isEyeHitStop)
            return false;

        if (OnEyeAction == null)
            return false;

        if (PlayerWork.IsFormSwim())
        {
            if (charaEntity == null)
                return false;

            if (!charaEntity.IsSwimCharacter())
                return false;
        }

        if (!IsEyeHit(FieldOBJ_DirDispGet(), ref moveVector, out _hitData.dir, ref hitpos))
            return false;

        return !Dpr.UI.UIManager.IsFieldOpenMenu();
    }
	private bool IsEyeHit(int dir, ref global::UnityEngine.Vector3 moveVector, out int hitdir, ref global::UnityEngine.Vector2 hitpos) {
        hitdir = dir;

        if (Mathf.Abs(playerPosition.y - Entity.worldPosition.y) > 1.0f)
            return false;

        if (IsForceEyeHit)
        {
            hitpos = new Vector2(EntityManager.activeFieldPlayer.worldPosition.x, EntityManager.activeFieldPlayer.worldPosition.z);
            return true;
        }

        int x = Entity.gridPosition.x;
        int z = Entity.gridPosition.y;
        int px = playerGridPosition.x;
        int pz = playerGridPosition.y;
        int eyeType = EyeType();
        float range = GameData.DataManager.GetFieldCommonParam(FieldCommon.ParamIndx.Trainer_EncountGridSize);

        if (eyeType == 1)
        {
            int count = 0;
            while (count < 2)
            {
                int length = MoveParam0;
                if (count > 0)
                    length = EyeObjectCheck(dir, length);

                if (length < 1)
                    return false;

                bool onLine = false;
                int gx = x;
                int gz = z;
                for (int i = 0; i < length; i++)
                {
                    switch (dir)
                    {
                        case (int)DIR.DIR_UP: gz--; break;
                        case (int)DIR.DIR_DOWN: gz++; break;
                        case (int)DIR.DIR_LEFT: gx--; break;
                        case (int)DIR.DIR_RIGHT: gx++; break;
                    }

                    if (gx == px && gz == pz)
                    {
                        onLine = true;
                        break;
                    }
                }

                if (!onLine)
                    return false;

                Vector2 eyePos = new Vector2(Entity.worldPosition.x, Entity.worldPosition.z);
                Vector2 eyeVec = Vector2.zero;
                float eyeLength = length + 0.499999f;
                switch (dir)
                {
                    case (int)DIR.DIR_UP: eyeVec.y = -eyeLength; break;
                    case (int)DIR.DIR_DOWN: eyeVec.y = eyeLength; break;
                    case (int)DIR.DIR_LEFT: eyeVec.x = eyeLength; break;
                    case (int)DIR.DIR_RIGHT: eyeVec.x = -eyeLength; break;
                }

                Vector2 playerPos = new Vector2(playerPosition.x, playerPosition.z);
                Vector2 moveDir = new Vector2(moveVector.x, moveVector.z).normalized;
                Vector2 cross = Vector2.zero;
                if (Dpr.Field.FieldCalc.LineCross(ref playerPos, ref moveDir, ref eyePos, ref eyeVec, out cross) != 0)
                {
                    if (dir == (int)DIR.DIR_UP || dir == (int)DIR.DIR_DOWN)
                    {
                        if (!(Mathf.Abs(playerPos.x - eyePos.x) < range))
                            return false;
                        if (Mathf.Abs(playerPos.y - eyePos.y) > eyeLength)
                            return false;

                        hitpos = playerPos;
                        count++;
                    }
                    else if (dir == (int)DIR.DIR_LEFT || dir == (int)DIR.DIR_RIGHT)
                    {
                        if (Mathf.Abs(playerPos.x - eyePos.x) > eyeLength)
                            return false;
                        if (!(Mathf.Abs(playerPos.y - eyePos.y) < range))
                            return false;

                        hitpos = playerPos;
                        count++;
                    }
                    // Any other dir loops again without counting (shipped, @01d5d9a0 back to the loop head).
                }
                else
                {
                    if (dir == (int)DIR.DIR_UP || dir == (int)DIR.DIR_DOWN)
                    {
                        if (Mathf.Abs(playerPos.x - cross.x) > Mathf.Abs(moveVector.x))
                            return false;
                    }
                    else if (dir == (int)DIR.DIR_LEFT || dir == (int)DIR.DIR_RIGHT)
                    {
                        if (Mathf.Abs(playerPos.y - cross.y) > Mathf.Abs(moveVector.z))
                            return false;
                    }

                    hitpos = cross;
                    count++;
                }
            }

            return true;
        }
        else if (eyeType == 2)
        {
            bool found = false;
            for (int i = 0; i < DIR_4_MAX; i++)
            {
                dir = i;
                int length = MoveParam0;
                if (length < 1)
                    continue;

                bool onLine = false;
                int gx = x;
                int gz = z;
                for (int k = 0; k < length; k++)
                {
                    switch (dir)
                    {
                        case (int)DIR.DIR_UP: gz--; break;
                        case (int)DIR.DIR_DOWN: gz++; break;
                        case (int)DIR.DIR_LEFT: gx--; break;
                        case (int)DIR.DIR_RIGHT: gx++; break;
                    }

                    if (gx == px && gz == pz)
                    {
                        onLine = true;
                        break;
                    }
                }

                if (!onLine)
                    continue;

                Vector2 eyePos = new Vector2(Entity.worldPosition.x, Entity.worldPosition.z);
                Vector2 eyeVec = Vector2.zero;
                switch (dir)
                {
                    case (int)DIR.DIR_UP: eyeVec.y = length; break;
                    case (int)DIR.DIR_DOWN: eyeVec.y = -length; break;
                    case (int)DIR.DIR_LEFT: eyeVec.x = -length; break;
                    case (int)DIR.DIR_RIGHT: eyeVec.x = length; break;
                }

                Vector2 playerPos = new Vector2(playerPosition.x, playerPosition.z);
                Vector2 moveDir = new Vector2(moveVector.x, moveVector.z);
                if (moveVector.x == 0.0f && moveVector.y == 0.0f && moveVector.z == 0.0f)
                {
                    hitpos = playerPos;
                    hitdir = dir;
                    found = true;
                    break;
                }

                Vector2 cross = Vector2.zero;
                if (Dpr.Field.FieldCalc.LineCross(ref playerPos, ref moveDir, ref eyePos, ref eyeVec, out cross) == 0)
                {
                    hitdir = dir;
                    found = true;
                    break;
                }

                float distX = Mathf.Abs(playerPos.x - eyePos.x);
                float distY = Mathf.Abs(playerPos.y - eyePos.y);
                if (dir == (int)DIR.DIR_DOWN || dir == (int)DIR.DIR_UP)
                {
                    if (distX < range && distY <= length)
                    {
                        hitdir = dir;
                        found = true;
                    }
                }
                else if (dir == (int)DIR.DIR_LEFT || dir == (int)DIR.DIR_RIGHT)
                {
                    if (distX <= length && distY < range)
                    {
                        hitdir = dir;
                        found = true;
                    }
                }
            }

            if (!found)
                return false;

            dir = hitdir;

            int hitLength = EyeObjectCheck(dir, MoveParam0);
            if (hitLength < 1)
                return false;

            bool hitOnLine = false;
            int hx = x;
            int hz = z;
            for (int k = 0; k < hitLength; k++)
            {
                switch (dir)
                {
                    case (int)DIR.DIR_UP: hz--; break;
                    case (int)DIR.DIR_DOWN: hz++; break;
                    case (int)DIR.DIR_LEFT: hx--; break;
                    case (int)DIR.DIR_RIGHT: hx++; break;
                }

                if (hx == px && hz == pz)
                {
                    hitOnLine = true;
                    break;
                }
            }

            if (!hitOnLine)
                return false;

            Vector2 hitEyePos = new Vector2(Entity.worldPosition.x, Entity.worldPosition.z);
            Vector2 hitEyeVec = Vector2.zero;
            switch (dir)
            {
                case (int)DIR.DIR_UP: hitEyeVec.y = hitLength; break;
                case (int)DIR.DIR_DOWN: hitEyeVec.y = -hitLength; break;
                case (int)DIR.DIR_LEFT: hitEyeVec.x = -hitLength; break;
                case (int)DIR.DIR_RIGHT: hitEyeVec.x = hitLength; break;
            }

            Vector2 hitPlayerPos = new Vector2(playerPosition.x, playerPosition.z);
            Vector2 hitMoveDir = new Vector2(moveVector.x, moveVector.z);
            if (moveVector == Vector3.zero)
            {
                hitpos = hitPlayerPos;
                hitdir = dir;
                return true;
            }

            Vector2 hitCross = Vector2.zero;
            if (Dpr.Field.FieldCalc.LineCross(ref hitPlayerPos, ref hitMoveDir, ref hitEyePos, ref hitEyeVec, out hitCross) == 0)
            {
                hitpos = hitCross;
                hitdir = dir;
                return true;
            }

            float hitDistX = Mathf.Abs(hitPlayerPos.x - hitEyePos.x);
            float hitDistY = Mathf.Abs(hitPlayerPos.y - hitEyePos.y);
            if (dir == (int)DIR.DIR_DOWN || dir == (int)DIR.DIR_UP)
            {
                if (!(hitDistX < 0.15f))
                    return false;
                if (hitDistY > hitLength)
                    return false;
            }
            else if (dir == (int)DIR.DIR_LEFT || dir == (int)DIR.DIR_RIGHT)
            {
                if (hitDistX > hitLength)
                    return false;
                if (!(hitDistY < 0.15f))
                    return false;
            }
            else
            {
                return false;
            }

            hitdir = dir;
            return true;
        }

        return false;
    }
	private bool IsHit(float x, float y, float w, float h, global::UnityEngine.Vector2Int point) {
        return point.x >= x && point.x <= w && point.y >= y && point.y <= h;
    }
	private int EyeObjectCheck(int dir, int length) {
        if (length < 1)
            return 0;

        for (int i = 0; i < EvDataManager.Instanse._fieldObjectEntity.Count; i++)
        {
            if (length < 1)
                return 0;

            if (EvDataManager.Instanse._fieldObjectEntity[i] == null)
                continue;

            if (EvDataManager.Instanse._fieldObjectEntity[i] is FieldPokemonEntity)
                continue;

            int x = Entity.gridPosition.x;
            int z = Entity.gridPosition.y;
            int ox = EvDataManager.Instanse._fieldObjectEntity[i].gridPosition.x;
            int oz = EvDataManager.Instanse._fieldObjectEntity[i].gridPosition.y;

            if (dir == (int)DIR.DIR_UP || dir == (int)DIR.DIR_DOWN)
            {
                if (x != ox)
                    continue;
                if (Math.Abs(z - oz) > length)
                    continue;
            }
            else if (dir == (int)DIR.DIR_LEFT || dir == (int)DIR.DIR_RIGHT)
            {
                if (z != oz)
                    continue;
                if (Math.Abs(x - ox) > length)
                    continue;
            }
            else
            {
                continue;
            }

            for (int k = 1; k < length; k++)
            {
                int tx = x;
                int tz = z;
                switch (dir)
                {
                    case (int)DIR.DIR_UP: tz = z - k; break;
                    case (int)DIR.DIR_DOWN: tz = z + k; break;
                    case (int)DIR.DIR_LEFT: tx = x - k; break;
                    case (int)DIR.DIR_RIGHT: tx = x + k; break;
                }

                if (tx == ox && tz == oz)
                {
                    length = k - 1;
                    break;
                }
            }
        }

        Vector2Int grid = Entity.gridPosition;
        int ret = length;
        for (int k = 0; k < length + 1; k++)
        {
            GameManager.GetAttribute(grid, out int code, out int stop, false);
            switch (dir)
            {
                case (int)DIR.DIR_UP: grid.y--; break;
                case (int)DIR.DIR_DOWN: grid.y++; break;
                case (int)DIR.DIR_LEFT: grid.x--; break;
                case (int)DIR.DIR_RIGHT: grid.x++; break;
            }

            if (stop == 128)
                return ret;

            ret = k;
        }

        return ret;
    }
	public bool PlayerApproach(float time) {
        if (IsForceEyeHit)
        {
            IsForceEyeHit = false;
            return true;
        }

        Vector2 myPos = new Vector2(Entity.worldPosition.x, Entity.worldPosition.z);
        playerPosition = EntityManager.activeFieldPlayer.worldPosition;
        MoveCode = MV_DMY;

        if (BaseMoveCode == MV_TR_PAIR)
        {
            if (EvDataManager.Instanse.FieldObjectMoveCodes[_mvParam.tbl_no].Entity.logcount < 2)
            {
                Entity.yawAngle = Quaternion.LookRotation(new Vector3(playerPosition.x - Entity.worldPosition.x, 0.0f, playerPosition.z - Entity.worldPosition.z).normalized).eulerAngles.y;
                MoveCodeUpdateAfter(false, time);
                return true;
            }

            Vector3 parentPos = EvDataManager.Instanse.FieldObjectMoveCodes[_mvParam.tbl_no].Entity.logPosition[1];
            Entity.moveVector = Vector3.zero;

            float moveX = parentPos.x - myPos.x;
            float moveZ = parentPos.z - myPos.y;
            float playerX = playerPosition.x - myPos.x;
            float playerZ = playerPosition.z - myPos.y;

            if (Mathf.Abs(playerZ - moveZ) <= 1.0f)
            {
                float limit = playerX > 0.0f ? Mathf.Max(0.0f, playerX - 1.0f) : Mathf.Min(0.0f, playerX + 1.0f);
                if (moveX * limit >= 0.0f && Mathf.Abs(limit) < Mathf.Abs(moveX))
                    moveX = limit;
            }

            if (Mathf.Abs(playerX - moveX) <= 1.0f)
            {
                float limit = playerZ > 0.0f ? Mathf.Max(0.0f, playerZ - 1.0f) : Mathf.Min(0.0f, playerZ + 1.0f);
                if (moveZ * limit >= 0.0f && Mathf.Abs(limit) < Mathf.Abs(moveZ))
                    moveZ = limit;
            }

            if (moveX < 0.001f && moveX > -0.001f)
                moveX = 0.0f;
            if (moveZ < 0.001f && moveZ > -0.001f)
                moveZ = 0.0f;

            bool move = false;
            float angle = 0.0f;
            bool turn = true;
            if (moveX < 0.0f)
                angle = 270.0f;
            else if (moveX > 0.0f)
                angle = 90.0f;
            else if (moveZ < 0.0f)
                angle = 180.0f;
            else if (moveZ > 0.0f)
                angle = 0.0f;
            else
                turn = false;

            if (turn && Entity.yawAngle != angle && !_mvParam.krkr_start)
                move = UpdateAngle(angle, 22.5f, _mvParam.isZeroFrameAngle);

            if (moveX != 0.0f)
            {
#if PC_UNLOCKED_FPS
                if (moveX < -0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.x = -0.13333334f * PcPlatform.PcFrameClock.Frames;
                else if (moveX > 0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.x = 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                if (moveX < -0.13333334f)
                    Entity.moveVector.x = -0.13333334f;
                else if (moveX > 0.13333334f)
                    Entity.moveVector.x = 0.13333334f;
#endif
                else
                    Entity.moveVector.x = moveX;

                MoveCodeUpdateAfter(true, time);
                return false;
            }

            if (moveZ != 0.0f)
            {
#if PC_UNLOCKED_FPS
                if (moveZ < -0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.z = -0.13333334f * PcPlatform.PcFrameClock.Frames;
                else if (moveZ > 0.13333334f * PcPlatform.PcFrameClock.Frames)
                    Entity.moveVector.z = 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                if (moveZ < -0.13333334f)
                    Entity.moveVector.z = -0.13333334f;
                else if (moveZ > 0.13333334f)
                    Entity.moveVector.z = 0.13333334f;
#endif
                else
                    Entity.moveVector.z = moveZ;

                MoveCodeUpdateAfter(true, time);
                return false;
            }

            Entity.yawAngle = Quaternion.LookRotation(new Vector3(playerPosition.x - Entity.worldPosition.x, 0.0f, playerPosition.z - Entity.worldPosition.z).normalized).eulerAngles.y;
            MoveCodeUpdateAfter(move, time);
            return true;
        }

        switch (_hitData.seqNo)
        {
            case 0:
                switch ((DIR)_hitData.dir)
                {
                    case DIR.DIR_UP:
                        Entity.yawAngle = 180.0f;
                        break;
                    case DIR.DIR_DOWN:
                        Entity.yawAngle = 0.0f;
                        break;
                    case DIR.DIR_LEFT:
                        Entity.yawAngle = 90.0f;
                        break;
                    case DIR.DIR_RIGHT:
                        Entity.yawAngle = 270.0f;
                        break;
                }
                Entity.SetYawAngleDirect(Entity.yawAngle);

                _hitData.endpos.x = playerPosition.x;
                _hitData.endpos.y = playerPosition.z;
                bool lookNow;
                switch ((DIR)_hitData.dir)
                {
                    case DIR.DIR_UP:
                        _hitData.endpos.x = myPos.x;
                        _hitData.endpos.y = playerPosition.z + 1.0f;
                        _hitData.seqNo = 1;
                        lookNow = myPos.y - 1.5f <= playerPosition.z;
                        break;

                    case DIR.DIR_DOWN:
                        _hitData.endpos.x = myPos.x;
                        _hitData.endpos.y = playerPosition.z - 1.0f;
                        _hitData.seqNo = 1;
                        lookNow = myPos.y + 1.5f >= playerPosition.z;
                        break;

                    case DIR.DIR_LEFT:
                        _hitData.endpos.x = playerPosition.x - 1.0f;
                        _hitData.endpos.y = myPos.y;
                        _hitData.seqNo = 1;
                        lookNow = myPos.x + 1.5f >= playerPosition.x;
                        break;

                    case DIR.DIR_RIGHT:
                        _hitData.endpos.x = playerPosition.x + 1.0f;
                        _hitData.endpos.y = myPos.y;
                        _hitData.seqNo = 1;
                        lookNow = myPos.x - 1.5f <= playerPosition.x;
                        break;

                    default:
                        _hitData.seqNo = 1;
                        lookNow = false;
                        break;
                }

                if (lookNow)
                {
                    Entity.yawAngle = Quaternion.LookRotation(new Vector3(playerPosition.x - Entity.worldPosition.x, 0.0f, playerPosition.z - Entity.worldPosition.z).normalized).eulerAngles.y;
                    _hitData.seqNo = 2;
                    break;
                }
                goto case 1;

            case 1:
            {
                Vector3 move = Vector3.zero;
                bool arrived;
                switch ((DIR)_hitData.dir)
                {
                    case DIR.DIR_UP:
#if PC_UNLOCKED_FPS
                        move.z -= 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                        move.z -= 0.13333334f;
#endif
                        myPos.y += move.z;
                        arrived = myPos.y - 1.0f <= playerPosition.z;
                        break;

                    case DIR.DIR_DOWN:
#if PC_UNLOCKED_FPS
                        move.z += 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                        move.z += 0.13333334f;
#endif
                        myPos.y += move.z;
                        arrived = myPos.y + 1.0f >= playerPosition.z;
                        break;

                    case DIR.DIR_LEFT:
#if PC_UNLOCKED_FPS
                        move.x += 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                        move.x += 0.13333334f;
#endif
                        myPos.x += move.x;
                        arrived = myPos.x + 1.0f >= playerPosition.x;
                        break;

                    case DIR.DIR_RIGHT:
#if PC_UNLOCKED_FPS
                        move.x -= 0.13333334f * PcPlatform.PcFrameClock.Frames;
#else
                        move.x -= 0.13333334f;
#endif
                        myPos.x += move.x;
                        arrived = myPos.x - 1.0f <= playerPosition.x;
                        break;

                    default:
                        arrived = false;
                        break;
                }

                if (arrived)
                {
                    Entity.worldPosition.x = _hitData.endpos.x;
                    Entity.worldPosition.z = _hitData.endpos.y;
                    Entity.yawAngle = Quaternion.LookRotation(new Vector3(playerPosition.x - Entity.worldPosition.x, 0.0f, playerPosition.z - Entity.worldPosition.z).normalized).eulerAngles.y;
                    _hitData.seqNo++;
                }
                else
                {
                    float playerAngle = Quaternion.LookRotation(new Vector3(myPos.x - playerPosition.x, 0.0f, myPos.y - playerPosition.z).normalized).eulerAngles.y;
#if PC_UNLOCKED_FPS
                    EntityManager.activeFieldPlayer.yawAngle += (playerAngle - EntityManager.activeFieldPlayer.yawAngle) * (1f - Mathf.Pow(1f - 0.5f, PcPlatform.PcFrameClock.Frames));
#else
                    EntityManager.activeFieldPlayer.yawAngle += (playerAngle - EntityManager.activeFieldPlayer.yawAngle) * 0.5f;
#endif
                    Entity.moveVector = move;
                    MoveCodeUpdateAfter(true, time);
                }
                break;
            }
        }

        if (_hitData.seqNo == 2)
        {
            MoveCodeUpdateAfter(false, time);
            return true;
        }

        return false;
    }
	public bool IsTrainer() {
        switch (Ev_Type)
        {
            case EV_TYPE_TRAINER:
            case EV_TYPE_TRAINER_EYEALL:
            case EV_TYPE_ITEM:
            case EV_TYPE_TRAINER_KYORO:
            case EV_TYPE_TRAINER_SPIN_STOP_L:
            case EV_TYPE_TRAINER_SPIN_STOP_R:
            case EV_TYPE_TRAINER_SPIN_MOVE_L:
            case EV_TYPE_TRAINER_SPIN_MOVE_R:
                return true;
            default:
                return false;
        }
    }
	public int EyeType() {
        switch (Ev_Type)
        {
            case EV_TYPE_TRAINER_EYEALL:
                return 2;
            case EV_TYPE_ITEM:
                return 3;
            default:
                return 1;
        }
    }
	public void SetPlayerDistance(int gx, int gz, float h) {
        float diffH = h - Entity.worldPosition.y;
        IsPlayerHeight = diffH * diffH <= 1.0f;

        int x = (int)(0.5f - Entity.worldPosition.x);
        int z = (int)(Entity.worldPosition.z + 0.5f);
        int dx = x - gx;
        int dz = z - gz;
        PlayerGridDistance = dx * dx + dz * dz;
    }
	private void SetMVCodeLimit() {
        int x = Math.Abs(_mv_defaultPosition.x);
        int z = Math.Abs(_mv_defaultPosition.z);

        _movelimit_Min.x = x;
        _movelimit_Max.x = x;
        _movelimit_Min.y = z;
        _movelimit_Max.y = z;

        switch (MoveCode)
        {
            case MV_RND:
                _movelimit_Min.x -= MoveLimitX;
                _movelimit_Max.x += MoveLimitX;
                _movelimit_Min.y -= MoveLimitZ;
                _movelimit_Max.y += MoveLimitZ;
                break;

            case MV_RND_V:
            case MV_RND_UD:
                _movelimit_Min.y -= MoveLimitZ;
                _movelimit_Max.y += MoveLimitZ;
                break;

            case MV_RND_H:
                _movelimit_Min.x -= MoveLimitX;
                _movelimit_Max.x += MoveLimitX;
                break;

            case MV_RND_UL:
            case MV_RTULRD:
            case MV_RTLUDR:
            case MV_RTUDLR:
            case MV_RTLRUD:
            case MV_RTUL:
            case MV_RTLU:
                _movelimit_Min.x -= MoveLimitX;
                _movelimit_Min.y -= MoveLimitZ;
                break;

            case MV_RND_UR:
            case MV_RTURLD:
            case MV_RTUDRL:
            case MV_RTRLUD:
            case MV_RTRUDL:
            case MV_RTRU:
            case MV_RTUR:
                _movelimit_Max.x += MoveLimitX;
                _movelimit_Min.y -= MoveLimitZ;
                break;

            case MV_RND_DL:
            case MV_RTLDUR:
            case MV_RTLRDU:
            case MV_RTDULR:
            case MV_RTDLRU:
            case MV_RTLD:
            case MV_RTDL:
                _movelimit_Min.x -= MoveLimitX;
                _movelimit_Max.y += MoveLimitZ;
                break;

            case MV_RND_DR:
            case MV_RTRLDU:
            case MV_RTDURL:
            case MV_RTRDUL:
            case MV_RTDRLU:
            case MV_RTDR:
            case MV_RTRD:
                _movelimit_Max.x += MoveLimitX;
                _movelimit_Max.y += MoveLimitZ;
                break;

            case MV_RND_UDL:
                _movelimit_Min.x -= MoveLimitX;
                _movelimit_Min.y -= MoveLimitZ;
                _movelimit_Max.y += MoveLimitZ;
                break;

            case MV_RND_UDR:
                _movelimit_Max.x += MoveLimitX;
                _movelimit_Min.y -= MoveLimitZ;
                _movelimit_Max.y += MoveLimitZ;
                break;

            case MV_RND_ULR:
                _movelimit_Min.y -= MoveLimitZ;
                _movelimit_Max.x += MoveLimitX;
                _movelimit_Min.x -= MoveLimitX;
                break;

            case MV_RND_DLR:
                _movelimit_Max.x += MoveLimitX;
                _movelimit_Min.x -= MoveLimitX;
                _movelimit_Max.y += MoveLimitZ;
                break;

            case MV_RND_LR:
                _movelimit_Max.x += MoveLimitX;
                _movelimit_Min.x -= MoveLimitX;
                break;

            case MV_RT2:
                switch (MoveDirHead)
                {
                    case DIR.DIR_UP:
                        _movelimit_Min.y -= MoveLimitZ;
                        break;

                    case DIR.DIR_DOWN:
                        _movelimit_Max.y += MoveLimitZ;
                        break;

                    case DIR.DIR_LEFT:
                        _movelimit_Min.x -= MoveLimitX;
                        break;

                    case DIR.DIR_RIGHT:
                        _movelimit_Max.x += MoveLimitX;
                        break;
                }
                break;
        }
    }
